from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["dashboard"])


@router.get("/dashboard", response_class=HTMLResponse)
def dashboard_view() -> HTMLResponse:
    return HTMLResponse(DASHBOARD_HTML)


DASHBOARD_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ATLAS Live Trading Intelligence</title>
<style>
:root{color-scheme:dark;--card:#0d131d;--line:#253247;--text:#f2f5f9;--muted:#8e9bad;--orange:#ff8a24;--green:#39d98a;--red:#ff6174;--yellow:#f6c85f}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#172336 0,#06080d 42%);color:var(--text);font:14px Inter,system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{display:flex;gap:12px;align-items:center}.logo{width:46px;height:46px;border:1px solid var(--orange);border-radius:15px;display:grid;place-items:center;font-weight:900;color:var(--orange)}.title{font-size:23px;font-weight:900;letter-spacing:.05em}.sub,.mini{font-size:11px;color:var(--muted)}.actions{display:flex;gap:8px;align-items:center}.btn{color:#090b0f;background:var(--orange);text-decoration:none;padding:10px 13px;border-radius:11px;font-weight:900}.badge{border:1px solid var(--line);padding:9px 11px;border-radius:999px;font-weight:800}.grid{display:grid;gap:12px}.stats{grid-template-columns:repeat(6,1fr)}.split{grid-template-columns:1.65fr 1fr}.card{background:linear-gradient(180deg,#111824,#0b111a);border:1px solid var(--line);border-radius:17px;padding:16px;box-shadow:0 16px 45px #0006}.label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.11em}.big{font-size:24px;font-weight:900;margin-top:6px}.green{color:var(--green)}.red{color:var(--red)}.yellow{color:var(--yellow)}.row{display:grid;grid-template-columns:1.2fr .8fr .7fr .7fr .65fr;gap:8px;padding:10px 0;border-bottom:1px solid var(--line);align-items:center}.market{display:grid;grid-template-columns:1.1fr .8fr .6fr .45fr;gap:8px;padding:9px 0;border-bottom:1px solid var(--line);align-items:center}.pos{display:grid;grid-template-columns:1fr .65fr .75fr .7fr;gap:8px;padding:9px 0;border-bottom:1px solid var(--line)}.tag{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:10px}.empty{color:var(--muted);padding:12px 0}.notice{border-left:3px solid var(--orange);padding:10px 12px;background:#ff8a240b;border-radius:8px;color:#bdc7d3;margin-top:12px}.story{display:block;padding:10px 0;border-bottom:1px solid var(--line);color:var(--text);text-decoration:none}.story:hover{color:var(--orange)}@media(max-width:1100px){.stats{grid-template-columns:repeat(3,1fr)}.split{grid-template-columns:1fr}}@media(max-width:720px){main{padding:12px}.stats{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}.row,.pos,.market{grid-template-columns:1fr 1fr}}
</style></head><body><main>
<div class="top"><div class="brand"><div class="logo">A</div><div><div class="title">ATLAS THE ULTIMATE</div><div class="sub">Subscriber Observatory · Read-only live telemetry</div></div></div><div class="actions"><a class="btn" href="/subscribe">Reader plans</a><div class="badge" id="status">CONNECTING</div></div></div>
<div class="grid stats"><div class="card"><div class="label">Account Type</div><div class="big" id="accountType">—</div></div><div class="card"><div class="label">Equity</div><div class="big" id="equity">—</div></div><div class="card"><div class="label">Balance</div><div class="big" id="balance">—</div></div><div class="card"><div class="label">Floating P/L</div><div class="big" id="floating">—</div></div><div class="card"><div class="label">Open Positions</div><div class="big" id="openPositions">—</div></div><div class="card"><div class="label">Execution Gate</div><div class="big yellow" id="execution">—</div></div></div>
<div class="grid split" style="margin-top:12px"><section class="card"><div class="label">ATLAS Opportunity Matrix</div><div id="signals"></div></section><section class="card"><div class="label">Verified Account</div><div id="account"></div><div class="label" style="margin-top:18px">Open Positions</div><div id="positions"></div></section></div>
<div class="grid split" style="margin-top:12px"><section class="card"><div class="label">Wall Street Board · Context only</div><div id="marketBoard"></div></section><section class="card"><div class="label">Financial News · Context only</div><div id="headlines"></div></section></div>
<div class="notice" id="disclaimer">Read-only telemetry. Trading involves risk.</div></main>
<script>
function el(id){return document.getElementById(id)}function esc(value){return String(value==null?"":value).replace(/[&<>'"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]})}function money(value,currency){if(value==null)return "PRIVATE";return Number(value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+(currency?" "+currency:"")}function tone(value){return Number(value)>=0?"green":"red"}
function signalRow(x){return '<div class="row"><div><b>'+esc(x.canonical_symbol||x.symbol)+'</b><div class="mini">'+esc(x.asset_class)+' · '+esc(x.symbol)+'</div></div><div><span class="tag">'+esc(x.decision.bias)+'</span><div class="mini">'+esc(x.decision.decision)+'</div></div><div><b>'+Number(x.decision.score||0).toFixed(1)+'</b><div class="mini">score</div></div><div><b>'+Number(x.quality.execution_confidence||0).toFixed(1)+'%</b><div class="mini">confidence</div></div><div><b>'+Number(x.opportunity_score||0).toFixed(0)+'</b><div class="mini">opportunity</div></div></div>'}
async function refresh(){try{var response=await fetch("/dashboard/atlas",{cache:"no-store"});if(!response.ok)throw Error("offline");var data=await response.json(),account=data.account||{};el("status").textContent=data.verified_live_account?"VERIFIED LIVE":"ONLINE";el("accountType").textContent=account.account_type||"—";el("accountType").className="big "+(account.account_type==="REAL"?"green":"yellow");el("equity").textContent=money(account.equity,account.currency);el("balance").textContent=money(account.balance,account.currency);el("floating").textContent=money(data.floating_position_pnl,account.currency);el("floating").className="big "+tone(data.floating_position_pnl);el("openPositions").textContent=data.open_positions||0;el("execution").textContent=data.services.execution_gate;el("account").innerHTML='<div class="pos"><span>'+esc(account.label)+'</span><b>'+esc(account.login)+'</b><span>'+esc(account.server)+'</span><b>1:'+esc(account.leverage||"—")+'</b></div>';el("signals").innerHTML=(data.symbols||[]).map(signalRow).join("")||'<div class="empty">No markets available.</div>';el("positions").innerHTML=(data.positions||[]).map(function(p){return '<div class="pos"><div><b>'+esc(p.symbol)+'</b><div class="mini">'+esc(p.direction)+'</div></div><div>'+p.volume+'</div><div>'+p.price_open+'</div><div class="'+tone(p.profit)+'"><b>'+Number(p.profit||0).toFixed(2)+'</b></div></div>'}).join("")||'<div class="empty">No open positions.</div>';el("disclaimer").textContent=data.disclaimer}catch(error){el("status").textContent="OFFLINE"}}
async function refreshBriefing(){try{var response=await fetch("/dashboard/market-briefing",{cache:"no-store"});var data=await response.json();if(!response.ok)throw Error("unavailable");el("marketBoard").innerHTML=(data.market_board||[]).map(function(x){return '<div class="market"><div><b>'+esc(x.label)+'</b><div class="mini">'+esc(x.category)+'</div></div><b>'+(x.price==null?"—":Number(x.price).toLocaleString())+'</b><b class="'+tone(x.change_percent)+'">'+(x.change_percent==null?"—":Number(x.change_percent).toFixed(2)+"%")+'</b><span class="tag">'+esc(x.market_state)+'</span></div>'}).join("")||'<div class="empty">Market data temporarily unavailable.</div>';el("headlines").innerHTML=(data.headlines||[]).map(function(x){return '<a class="story" href="'+esc(x.url)+'" target="_blank" rel="noopener"><b>'+esc(x.title)+'</b><div class="mini">'+esc(x.source)+" · "+esc(x.published_at)+'</div></a>'}).join("")||'<div class="empty">Financial headlines temporarily unavailable.</div>'}catch(error){el("marketBoard").innerHTML='<div class="empty">Market board unavailable.</div>';el("headlines").innerHTML='<div class="empty">Headlines unavailable.</div>'}}
refresh();refreshBriefing();setInterval(refresh,5000);setInterval(refreshBriefing,60000);
</script></body></html>'''
